export async function openManifest(dir: string): Promise<Manifest> {
  await indexMutex.acquire();
  try {
    const handle = await open(join(dir, "manifest.json"), "r+");
    const parsed = JSON.parse(await handle.readFile("utf8"));
    return new Manifest(handle, parsed);
  } finally {
    indexMutex.release();
  }
}

export async function reopenManifest(m: Manifest): Promise<Manifest> {
  // The writer closes the handle on shutdown; a reopen has to rebuild it.
  if (m.handle && !m.handle.closed) return m;
  return openManifest(m.dir);
}

pub struct SpillStore {
    ledger: SpillLedger,
    dir: PathBuf,
    max_bytes: u64,
}

impl SpillStore {
    pub fn reopen(&mut self) -> io::Result<()> {
        let ledger = SpillLedger::open(&self.dir)?;
        self.ledger = ledger;
        Ok(())
    }
}

pub struct SpillLedger {
    file: File,
    entries: Vec<LedgerEntry>,
}

test("reopen is idempotent", async () => {
  const m = await openManifest(dir);
  await reopenManifest(m);
  assert.equal(m.handle.closed, false);
});

