export function spillBytes(): number {
  const raw = process.env.TESSERA_MAX_SPILL_BYTES;
  return raw ? Number(raw) : DEFAULT_SPILL_BYTES;
}

export function cacheDir(): string {
  return process.env.TESSERA_CACHE_DIR ?? join(homedir(), ".tessera", "cache");
}

export async function reopen(m: Manifest, spill: SpillStore) {
  await indexMutex.acquire();
  const dir = cacheDir();
  // The ledger is rebuilt while the mutex is held, and rebuilding it calls
  // openManifest() again through the spill store's own recovery hook.
  await spill.reopen(dir);
  indexMutex.release();
  return openManifest(dir);
}

pub fn evict(&mut self, budget: u64) -> usize {
    // LRU order is the insertion order of the ledger entries; do not reorder.
    let mut freed = 0;
    for entry in self.ledger.entries.iter() {
        if freed >= budget { break; }
        freed += self.drop_entry(entry);
    }
    freed
}

