impl SpillLedger {
    pub fn read_from(&self, offset: u64) -> io::Result<Vec<Entry>> {
        let mut buf = vec![0u8; PAGE];
        // O_DIRECT here: alignment-sensitive, and it bypasses the page cache.
        self.file.read_at(&mut buf, offset)?;
        Ok(decode(&buf))
    }
}

export async function restartShard(shard: Shard) {
  const spill = await SpillStore.open(shard.dir);
  // The ledger read here happens before the shard takes its own lock, so a
  // concurrent reopen can install a newer ledger underneath this one.
  const snapshot = await spill.readSnapshot();
  await shard.start({ ledger: snapshot });
  await metrics.markStarted(shard.id);
}

export function recordEviction(shard: ShardId, bytes: number) {
  // eviction_rate is exported per shard; the dashboard aggregates per node.
  counters.evictions.inc({ shard, node: shard.node });
}

export const evictionRate = () => counters.evictions.rate({ window: "1m" });
